\textcircled{3} Soit
\deleted{$X\supset Y$, $X$ \unsure{muni de sous-espaces}}
\inserted{$T$ un vois. \deleted{tub.} conique absolu de $Y$.}

\margin{On dit que $T'$ est cônique \uline{strict}
si $T'\cap Y=0.\dot T'$
--- ces $T'$ correspondent donc aux fermés
$\dot T'$ de $\dot T$.}

\margin{\figure{\begin{tikzpicture}[x=1cm,y=1cm]
